export const CLI_SCHEMA_VERSION = 1;

export const CLI_EXIT_CODES = {
  ok: 0,
  operationFailed: 1,
  usageError: 2,
  authRequired: 3,
  serverUnavailable: 4,
  waitTimeout: 5,
} as const;

export type CliExitCode = (typeof CLI_EXIT_CODES)[keyof typeof CLI_EXIT_CODES];

export type CliErrorCode =
  | 'OPERATION_FAILED'
  | 'USAGE_ERROR'
  | 'AUTH_REQUIRED'
  | 'SERVER_UNAVAILABLE'
  | 'WAIT_TIMEOUT'
  | 'SESSION_NOT_FOUND'
  | 'WORK_ITEM_NOT_FOUND'
  | 'DIRECTION_AMBIGUOUS'
  | 'MCP_REMOVED';

export type CliLoginAction = {
  action: 'login';
  command: 'rivet login';
  mcpTool: 'rivet_login';
  authUrl?: string;
};

export const AUTH_REQUIRED_MESSAGE =
  'Authentication required. Run `rivet open` to open Rivet sign-in in the browser, or call the rivet_login MCP tool if this host has it. `rivet login` also works when the user runs it.';

export type CliOpenProjectAction = {
  action: 'open_project';
  command: 'rivet open';
  args: ['--project', string];
};

export type CliEditorDescriptor = {
  target: { projectPath: string; projectId?: string };
  open: CliOpenProjectAction;
};

export type CliRetryAction = {
  action: 'retry';
  delayMs: number;
};

export type CliRecoveryAction =
  CliLoginAction | CliOpenProjectAction | CliRetryAction;

export type CliErrorRecovery =
  | {
      isRecoverable: true;
      nextAction?: CliRecoveryAction;
    }
  | {
      isRecoverable: false;
      nextAction?: never;
    };

export type CliErrorEnvelope = {
  schemaVersion: typeof CLI_SCHEMA_VERSION;
  ok: false;
  command: string;
  error: {
    code: CliErrorCode;
    message: string;
    isRecoverable?: boolean;
    nextAction?: CliRecoveryAction;
    details?: unknown;
  };
};

export type CliOkEnvelope<TData = unknown> = {
  schemaVersion: typeof CLI_SCHEMA_VERSION;
  ok: true;
  command: string;
  data: TData;
};

export type CliEnvelope<TData = unknown> =
  CliOkEnvelope<TData> | CliErrorEnvelope;

export type CliCommandResult = {
  envelope: CliEnvelope;
  exitCode: CliExitCode;
  cause?: unknown;
};

export const okResult = (command: string, data: unknown): CliCommandResult => ({
  envelope: { schemaVersion: CLI_SCHEMA_VERSION, ok: true, command, data },
  exitCode: CLI_EXIT_CODES.ok,
});

const ERROR_EXIT_CODES: Record<CliErrorCode, CliExitCode> = {
  OPERATION_FAILED: CLI_EXIT_CODES.operationFailed,
  USAGE_ERROR: CLI_EXIT_CODES.usageError,
  AUTH_REQUIRED: CLI_EXIT_CODES.authRequired,
  SERVER_UNAVAILABLE: CLI_EXIT_CODES.serverUnavailable,
  WAIT_TIMEOUT: CLI_EXIT_CODES.waitTimeout,
  SESSION_NOT_FOUND: CLI_EXIT_CODES.operationFailed,
  WORK_ITEM_NOT_FOUND: CLI_EXIT_CODES.operationFailed,
  DIRECTION_AMBIGUOUS: CLI_EXIT_CODES.usageError,
  MCP_REMOVED: CLI_EXIT_CODES.usageError,
};

export const loginRecovery = (authUrl?: string): CliErrorRecovery => ({
  isRecoverable: true,
  nextAction: {
    action: 'login',
    command: 'rivet login',
    mcpTool: 'rivet_login',
    ...(authUrl ? { authUrl } : {}),
  },
});

const recoveryForError = (code: CliErrorCode): CliErrorRecovery | undefined =>
  code === 'AUTH_REQUIRED' ? loginRecovery() : undefined;

export const errorResult = (
  command: string,
  code: CliErrorCode,
  message: string,
  details?: unknown,
  explicitRecovery?: CliErrorRecovery,
): CliCommandResult => {
  const recovery = explicitRecovery ?? recoveryForError(code);
  return {
    envelope: {
      schemaVersion: CLI_SCHEMA_VERSION,
      ok: false,
      command,
      error: {
        code,
        message,
        ...(recovery ?? {}),
        ...(details === undefined ? {} : { details }),
      },
    },
    exitCode: ERROR_EXIT_CODES[code],
  };
};

export const serializeEnvelope = (envelope: CliEnvelope): string =>
  JSON.stringify(envelope);
